import { writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';

// 150 individually composed layouts. Coordinates are authored in the format's
// own aspect ratio; color and wording variants do not count as new designs.
const templates = [];
let layers, bg, ink, accent, W, H;
const add = o => layers.push({ originX:'left', originY:'top', angle:0, strokeWidth:0, opacity:1, ...o });
const R = (x,y,w,h,c=accent,r=0) => add({type:'Rect',name:'Color panel',left:x,top:y,width:w,height:h,fill:c,rx:r,ry:r});
const E = (x,y,w,h,c=accent) => add({type:'Ellipse',name:'Ellipse',left:x,top:y,rx:w/2,ry:h/2,fill:c});
const T = (text,x,y,w,size=40,font='Arial',c=ink,weight='normal',align='left',boxHeight) => add({type:'Textbox',name:text.replaceAll('\n',' ').slice(0,60),text,left:x,top:y,width:w,fontSize:size,fontFamily:font,fill:c,fontWeight:weight,textAlign:align,lineHeight:1.06,...(boxHeight?{boxHeight}: {})});
const L = (x,y,w,c=ink,h=2) => R(x,y,w,h,c);
const P = (path,x,y,s=1,c=accent) => add({type:'Path',name:'Vector illustration',path,left:x,top:y,scaleX:s,scaleY:s,fill:c});
const photo = (src,x,y,w,h) => add({type:'Photo',name:'Photograph',src,left:x,top:y,width:w,height:h});
const ring = (x,y,d,c=accent,t=8) => {E(x,y,d,d,c);E(x+t,y+t,d-2*t,d-2*t,bg);};
const arrow = (x,y,w=240,h=120,c=accent) => P(`M0 ${h*.32} H${w*.65} V0 L${w} ${h/2} L${w*.65} ${h} V${h*.68} H0 Z`,x,y,1,c);
const star = (x,y,s=1,c=accent) => P('M50 0 L62 35 L100 38 L71 62 L80 100 L50 78 L20 100 L29 62 L0 38 L38 35Z',x,y,s,c);
const leaf = (x,y,s=1,c=accent) => P('M0 160 Q-15 20 110 0 Q135 125 0 160Z',x,y,s,c);
const arc = (x,y,w,h,c=accent) => P(`M0 ${w/2} A${w/2} ${w/2} 0 0 1 ${w} ${w/2} V${h} H0Z`,x,y,1,c);
const outline = (x,y,w,h,c=ink,t=2) => {L(x,y,w,c,t);L(x,y+h-t,w,c,t);R(x,y,t,h,c);R(x+w-t,y,t,h,c);};
function D(name, occasion, size, palette, recipe, format, pages) {
  [bg,ink,accent]=palette;[W,H]=size;layers=[];recipe();
  const id='studio-'+String(templates.length+1).padStart(3,'0');
  const composition=layers.map((o,i)=>({...o,id:`${id}-${i+1}`}));
  templates.push({id,name,occasion,category:occasion==='Business pitches'?'Presentation':'Print',width:W,height:H,background:bg,ink,accent,layout:'custom',font:'Arial',headline:composition.filter(o=>o.type==='Textbox').sort((a,b)=>b.fontSize-a.fontSize)[0]?.text||name,subtitle:occasion,format,thumbnail:`/templates/${id}.webp`,composition,...(pages?{pages}: {})});
}
const extra=(n,o,s,p,f)=>D(n,o,s,p,f,`${s[0]} × ${s[1]} px`);
