if (templates.length !== 150) throw new Error(`Expected 150 new templates, got ${templates.length}`);
const geometry = new Set();
for (const template of templates) {
  // Bound each text block by the next block in its column. The renderer uses
  // this authored space to fit font metrics without colliding with nearby copy.
  for (const layer of template.composition.filter(o => o.type === 'Textbox')) {
    const following = template.composition.filter(o => o.type === 'Textbox' && o.top > layer.top && o.left < layer.left + layer.width && o.left + o.width > layer.left);
    layer.boxHeight ??= Math.min(template.height - layer.top - 20, ...following.map(o => o.top - layer.top - 12));
  }
  const shape = template.composition.map(({fill,text,name,id,...layout}) => layout);
  const hash = createHash('sha256').update(JSON.stringify(shape)).digest('hex');
  if (geometry.has(hash)) throw new Error(`Repeated composition: ${template.name}`);
  geometry.add(hash);
}
const pitches = templates.filter(t => t.occasion === 'Business pitches');
for (let i=0; i<pitches.length; i+=4) pitches[i].deckIds = pitches.slice(i,i+4).map(t => t.id);
for (const template of templates) if (template.occasion === 'Social campaigns') template.category = 'Social';
writeFileSync('shared/templates-studio.json', JSON.stringify(templates,null,2)+'\n');
console.log(JSON.stringify({newTemplates:templates.length,distinctGeometry:geometry.size,deckSets:pitches.filter(t=>t.deckIds).length,categories:Object.fromEntries([...new Set(templates.map(t=>t.occasion))].map(o=>[o,templates.filter(t=>t.occasion===o).length]))}));
